package com.stocksense.warehouse; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/warehouses") @RequiredArgsConstructor public class WarehouseController { private final WarehouseRepository warehouses; private final LocationRepository locations; @GetMapping public List<Warehouse> all(){return warehouses.findAll();} @PostMapping public Warehouse create(@RequestBody Warehouse w){return warehouses.save(w);} @GetMapping("/{id}/locations") public List<Location> locations(@PathVariable Long id){return locations.findByWarehouseId(id);} @PostMapping("/{id}/locations") public Location add(@PathVariable Long id,@RequestBody Location l){l.setWarehouse(warehouses.findById(id).orElseThrow());return locations.save(l);} }
